import pathlib,re,collections
root=pathlib.Path('AlgebraicJacobian')
mods={'AlgebraicJacobian.'+str(f.relative_to(root)).replace('/','.')[:-5]:f for f in root.rglob('*.lean')}
deps=collections.defaultdict(set)
for m,f in mods.items():
    for line in f.read_text().splitlines():
        g=re.match(r'import (AlgebraicJacobian[\w.]*)',line)
        if g: deps[m].add(g.group(1))
rootf=pathlib.Path('AlgebraicJacobian.lean')
seeds={re.match(r'import (AlgebraicJacobian[\w.]*)',l).group(1) for l in rootf.read_text().splitlines() if re.match(r'import (AlgebraicJacobian[\w.]*)',l)}
seen=set(); stack=list(seeds)
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m); stack.extend(deps.get(m,()))
targets=[m for m in mods if 'BaseDivisorEveryField' in m or 'UniformRiemannRoch' in m or 'ExtensionUniformity' in m or 'VanishingFieldDescent' in m or 'FiberBound' in m]
for t in sorted(targets):
    print(('REACHABLE  ' if t in seen else 'UNREACHABLE'), t)
print()
print('total modules', len(mods), '| transitively reachable', len(seen), '| NOT reachable', len(mods)-len(seen))
